import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function money(value) {
  return Number(value || 0).toFixed(2);
}

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function val(value) {
  return String(value ?? "");
}

function formatDate(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("en-GB");
}

function formatDateTime(value) {
  if (!value) return "";
  return new Date(value).toLocaleString("en-GB");
}

function initials(name) {
  return val(name || "AX")
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map(x => x[0])
    .join("")
    .toUpperCase();
}

function orderPayload(header) {
  return [
    "SALES_ORDER",
    `DOCUMENT_ID=${header.documentId || ""}`,
    `ORDER_NO=${header.documentNumber || ""}`,
    `DATE=${header.documentDate || ""}`,
    `CUSTOMER=${header.partnerCode || header.partnerName || ""}`,
    `WAREHOUSE=${header.warehouseCode || ""}`,
    `TOTAL=${header.totalAmount || ""}`,
    `STATUS=${header.status || ""}`
  ].join("|");
}

function barcodeValue(header) {
  return val(header.documentNumber || header.orderNumber || "")
    .replace(/[^A-Za-z0-9-]/g, "");
}

function App() {
  const model = appsmith.model || {};
  const h = model.header || {};
  const items = model.items || [];
  const taxes = model.taxes || [];

  const [qr, setQr] = React.useState("");
  const barcodeRef = React.useRef(null);

  const key = `${h.documentId || ""}-${h.documentNumber || ""}-${h.status || ""}`;

  React.useEffect(() => {
    async function buildQr() {
      if (!h.documentNumber) return;

      setQr(await QRCode.toDataURL(orderPayload(h), {
        margin: 1,
        width: 150,
        errorCorrectionLevel: "M"
      }));
    }

    buildQr();
  }, [key]);

  React.useEffect(() => {
    const value = barcodeValue(h);

    if (!value || !barcodeRef.current) return;

    JsBarcode(barcodeRef.current, value, {
      format: "CODE128",
      displayValue: true,
      fontSize: 12,
      height: 46,
      margin: 0
    });
  }, [key]);

  if (!h.documentNumber) {
    return <div className="empty">No sales order data available.</div>;
  }

  const totalQty = items.reduce((s, r) => s + Number(r.quantity || 0), 0);
  const itemCount = items.length;

  return (
    <div className="page">
      <button className="print-button" onClick={() => window.print()}>
        Print sales order
      </button>

      <div className="document">
        <div className="top-line" />

        <div className="header">
          <div className="brand">
            {(h.companyLogoPath || h.company_logo_path || h.logo_path) ? (
              <img className="logo" src={h.companyLogoPath || h.company_logo_path || h.logo_path} />
            ) : (
              <div className="logo-fallback">{initials(h.companyName)}</div>
            )}

            <div>
              <div className="company-name">{h.companyName || "Company"}</div>
              <div className="company-meta">
                <div>{[h.companyAddress, h.companyPostalCode, h.companyCity].filter(Boolean).join(", ")}</div>
                <div>Tax No: {h.companyTaxNumber || "-"}</div>
                <div>Reg No: {h.companyRegistrationNumber || "-"}</div>
                <div>{[h.companyEmail, h.companyPhone].filter(Boolean).join(" | ")}</div>
              </div>
            </div>
          </div>

          <div className="document-title">
            <div className="badge">Sales Order</div>
            <h1>ORDER</h1>
            <div className="doc-no">{h.documentNumber}</div>
            <div className="status">{h.status || "DRAFT"}</div>
          </div>
        </div>

        <div className="info-strip">
          <div className="info-box">
            <span className="label">Order Date</span>
            <span className="value">{formatDate(h.documentDate)}</span>
          </div>
          <div className="info-box">
            <span className="label">Due Date</span>
            <span className="value">{formatDate(h.dueDate)}</span>
          </div>
          <div className="info-box">
            <span className="label">Channel</span>
            <span className="value">{h.salesChannel || "-"}</span>
          </div>
          <div className="info-box">
            <span className="label">Fulfillment</span>
            <span className="value">{h.fulfillmentType || "-"}</span>
          </div>
          <div className="info-box">
            <span className="label">Created</span>
            <span className="value">{formatDateTime(h.createdAt)}</span>
          </div>
        </div>

        <div className="party-grid">
          <div className="party-box">
            <span className="label">Customer</span>
            <h2>{h.partnerLegalName || h.partnerName || "Customer"}</h2>
            <p>
              {h.partnerCode ? `Code: ${h.partnerCode}` : ""}
              {h.partnerTaxNumber ? ` | Tax No: ${h.partnerTaxNumber}` : ""}
            </p>
            <p>{[h.partnerAddress, h.partnerPostalCode, h.partnerCity].filter(Boolean).join(", ")}</p>
            <p>{[h.partnerEmail, h.partnerPhone].filter(Boolean).join(" | ")}</p>
          </div>

          <div className="party-box">
            <span className="label">Warehouse / Delivery</span>
            <h2>{[h.warehouseCode, h.warehouseName].filter(Boolean).join(" - ") || "-"}</h2>
            <p>Payment: {h.paymentMethod || "-"}</p>
            <p>Created by: {h.createdBy || model.username || "-"}</p>
            <p>Posting: {h.postingStatus || "-"}</p>
          </div>
        </div>

        <div className="items-wrap">
          <div className="items-head">
            <h2>Order Items</h2>
            <span>{itemCount} line{itemCount === 1 ? "" : "s"} / Qty {qty(totalQty)}</span>
          </div>

          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Product</th>
                <th>Description</th>
                <th className="right">Qty</th>
                <th>Unit</th>
                <th className="right">Price</th>
                <th className="right">Discount</th>
                <th className="right">Tax</th>
                <th className="right">Total</th>
              </tr>
            </thead>
            <tbody>
              {items.map((row, index) => (
                <tr key={index}>
                  <td>{row.lineNo || index + 1}</td>
                  <td>
                    <div className="product-code">{row.productCode || row.code || ""}</div>
                    <div className="product-name">
                      {row.productName || row.name || ""}
                      {row.barcode ? ` | ${row.barcode}` : ""}
                    </div>
                  </td>
                  <td>{row.description || row.productName || ""}</td>
                  <td className="right">{qty(row.quantity)}</td>
                  <td>{row.unitCode || row.unitName || row.unit || ""}</td>
                  <td className="right">{money(row.unitPrice)}</td>
                  <td className="right">{money(row.discountAmount)}</td>
                  <td className="right">{money(row.taxAmount)}</td>
                  <td className="right">{money(row.lineTotal)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="bottom-grid">
          <div>
            {(h.documentNote || h.note) && (
              <div className="note-box">
                <span className="label">Note</span>
                {h.documentNote || h.note}
              </div>
            )}

            <div className="reference-box">
              <span className="label">Document Reference</span>

              <div className="qr-row">
                <div className="qr-box">
                  {qr && <img src={qr} />}
                  <div>QR reference</div>
                </div>

                <div className="barcode-box">
                  <svg ref={barcodeRef}></svg>
                  <div>Scan order number</div>
                </div>
              </div>
            </div>
          </div>

          <div className="summary-box">
            <div className="summary-row">
              <span>Subtotal</span>
              <b>{money(h.subtotalAmount)} {h.currencyCode || "EUR"}</b>
            </div>
            <div className="summary-row">
              <span>Discount</span>
              <b>{money(h.discountAmount)} {h.currencyCode || "EUR"}</b>
            </div>
            <div className="summary-row">
              <span>Tax</span>
              <b>{money(h.taxAmount)} {h.currencyCode || "EUR"}</b>
            </div>
            <div className="summary-row total">
              <span>Total</span>
              <b>{money(h.totalAmount)} {h.currencyCode || "EUR"}</b>
            </div>
          </div>
        </div>

        {taxes.length > 0 && (
          <div className="items-wrap" style={{ marginTop: "18px" }}>
            <div className="items-head">
              <h2>Tax Summary</h2>
              <span>{taxes.length} rate{taxes.length === 1 ? "" : "s"}</span>
            </div>

            <table>
              <thead>
                <tr>
                  <th>Tax Rate</th>
                  <th className="right">Taxable</th>
                  <th className="right">Tax</th>
                  <th className="right">Total</th>
                </tr>
              </thead>
              <tbody>
                {taxes.map((tax, index) => (
                  <tr key={index}>
                    <td>{money(tax.taxRate)}%</td>
                    <td className="right">{money(tax.taxableAmount)}</td>
                    <td className="right">{money(tax.taxAmount)}</td>
                    <td className="right">{money(tax.totalAmount)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <div className="signatures">
          <div className="signature">Prepared by</div>
          <div className="signature">Customer confirmation</div>
        </div>

        <div className="footer">
          This sales order is not a fiscal invoice. Final invoice will be issued after confirmation and fulfillment.
        </div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
